import {installToolFormBehavior} from './form-behavior.mjs';
import {loadArticle,blogIndex,blogCard} from './blog.mjs';
import {tools,categories,icon} from './catalog.mjs';
import {e,notify,clearOutput} from './ui.mjs';
import {seoMeta,schemaData} from './content.mjs';
import {parsePage,pageHTML,navHTML,cardHTML,starHTML,filteredTools,href} from './views.mjs';
const main=document.querySelector('#main'),search=document.querySelector('#search'),baseURL=new URL(document.baseURI);
installToolFormBehavior(main);search.autocomplete='off';
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{}};
let cleanup=()=>{},observer,query='',page,layout=read('nepocore-layout','grid'),favorites=new Set(read('nepocore-favorites',[])),dark=read('nepocore-dark',false);
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
let motion=read('nepocore-motion',true)&&!reducedMotion.matches;
document.body.classList.toggle('dark',dark);
document.body.classList.toggle('motion-paused',!motion);
document.querySelector('#year').textContent=new Date().getFullYear();
document.querySelector('#search-icon').innerHTML=icon('search');
function themeButton(){document.querySelector('#theme-toggle').innerHTML=icon(dark?'sun':'moon');}
function motionButton(){const b=document.querySelector('#motion-toggle');if(!b)return;b.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${motion?'<path d="M8 5v14M16 5v14"/>':'<path d="m8 4 12 8-12 8z"/>'}</svg>`;b.setAttribute('aria-label',motion?'Pause animations':'Enable animations');b.title=motion?'Pause animations':'Enable animations';b.setAttribute('aria-pressed',String(!motion));}
themeButton();motionButton();
document.querySelector('#theme-toggle').onclick=()=>{dark=!dark;document.body.classList.toggle('dark',dark);save('nepocore-dark',dark);themeButton();};
document.querySelector('#motion-toggle').onclick=()=>{motion=!motion;document.body.classList.toggle('motion-paused',!motion);save('nepocore-motion',motion);motionButton();};
reducedMotion.addEventListener?.('change',ev=>{if(ev.matches){motion=false;document.body.classList.add('motion-paused');motionButton();}});
const sidebar=document.querySelector('.sidebar'),menu=document.querySelector('#menu-toggle');
const mobileNavigation=matchMedia('(min-width:0px)');
function syncSidebar(){const hidden=mobileNavigation.matches&&!sidebar.classList.contains('open');sidebar.inert=hidden;if(hidden)sidebar.setAttribute('aria-hidden','true');else sidebar.removeAttribute('aria-hidden');}
mobileNavigation.addEventListener?.('change',()=>{closeMenu();syncSidebar();});
const closeMenu=()=>{const restore=sidebar.contains(document.activeElement)&&mobileNavigation.matches;sidebar.classList.remove('open');menu.setAttribute('aria-expanded','false');document.querySelector('#menu-scrim').hidden=true;syncSidebar();if(restore)menu.focus();};
menu.onclick=()=>{const open=sidebar.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));document.querySelector('#menu-scrim').hidden=!open;syncSidebar();if(open)sidebar.querySelector('a')?.focus();};
document.addEventListener('keydown',ev=>{if(ev.key!=='Tab'||!mobileNavigation.matches||!sidebar.classList.contains('open'))return;const links=[...sidebar.querySelectorAll('a,summary,button')].filter(el=>el.getClientRects().length);const first=links[0],last=links.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}});
document.querySelector('#menu-scrim').onclick=closeMenu;
document.querySelector('.skip').onclick=ev=>{ev.preventDefault();main.focus();main.scrollIntoView();};
document.addEventListener('keydown',ev=>{if(((ev.key==='k'&&(ev.ctrlKey||ev.metaKey))||ev.key==='/')&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){ev.preventDefault();search.focus();}if(ev.key==='Escape'){closeMenu();search.blur();}});
const activeCategory=()=>page.type==='tool'?tools.find(t=>t.id===page.id)?.category:page.type==='category'?page.id:page.type==='favorites'?'favorites':['blog','blogCategory','article'].includes(page.type)?'guides':'all';
function nav(){document.querySelector('#side-nav').innerHTML=navHTML(activeCategory(),favorites.size);}
function metadata(){const m=seoMeta(page.type,page.id);document.title=m.title;const desc=document.querySelector('meta[name=description]');if(desc)desc.content=m.description;document.querySelector('meta[property="og:title"]')?.setAttribute('content',m.title);document.querySelector('meta[property="og:description"]')?.setAttribute('content',m.description);const canonical=new URL(m.path,baseURL).href;document.querySelector('link[rel=canonical]')?.setAttribute('href',canonical);document.querySelector('meta[property="og:url"]')?.setAttribute('content',canonical);document.querySelector('meta[name=robots]')?.setAttribute('content',m.noindex||query?'noindex,follow':'index,follow,max-image-preview:large');const t=tools.find(t=>t.id===page.id);document.querySelector('#breadcrumb').textContent=t?categories.find(c=>c.id===t.category).name+' / '+t.title:page.type==='category'?categories.find(c=>c.id===page.id).name:'Your space to get things done.';const graph=document.querySelector('#site-structured-data');if(graph)graph.textContent=JSON.stringify(schemaData(page,baseURL.href));}
function animate(){observer?.disconnect();if(!motion||!('IntersectionObserver'in window))return;observer=new IntersectionObserver(entries=>{for(const en of entries)if(en.isIntersecting){en.target.classList.add('animate-in');observer.unobserve(en.target);}},{threshold:.07});main.querySelectorAll('.tool-card,.featured-card,.guide-columns>section,.creator-intro').forEach((el,i)=>{el.style.setProperty('--stagger',(i%4)*45+'ms');observer.observe(el);});}
function renderCards(){const grid=main.querySelector('#catalog-grid');if(!grid)return;const category=page.type==='favorites'?'favorites':page.type==='category'?page.id:'all',list=filteredTools(category,query,favorites),visible=page.type==='home'&&!query?list.slice(0,16):list;grid.className='tool-grid '+(layout==='list'?'list':'');grid.innerHTML=visible.length?visible.map(t=>cardHTML(t,favorites)).join(''):`<div class="empty-state">${icon('search')}<h3>${category==='favorites'&&!query?'Your own little toolkit.':'No tools found.'}</h3><p>${category==='favorites'&&!query?'Tap the star on a tool to keep it here.':'Try image, IELTS, PDF, meme, or calculator.'}</p>${query?'<button class="btn secondary small" data-clear-search>Clear search</button>':''}</div>`;main.querySelector('#result-count').textContent=`${list.length} ${list.length===1?'tool':'tools'}${query?' found':''}`;main.querySelectorAll('[data-view]').forEach(b=>{const selected=b.dataset.view===layout;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});animate();}
function legacyRoute(){if(!location.hash.startsWith('#/'))return;const p=location.hash.slice(2).split('/');const target=p[0]==='tool'?href('tool',p[1]):p[0]==='category'?href('category',p[1]):p[0]==='tools'?href('catalog'):p[0]?href(p[0]):href('home');history.replaceState(null,'',new URL(target,baseURL));}
let activation=0;
const toolLoaders={scientific:()=>import('./scientific.mjs').then(m=>m.setupScientific),plusDocs:()=>import('./collections/plus-docs.mjs').then(m=>m.setupDocsPlus),plusVisual:()=>import('./collections/plus-visual.mjs').then(m=>m.setupVisualPlus),plusLearning:()=>import('./collections/plus-learning.mjs').then(m=>m.setupLearningPlus),plusSecurity:()=>import('./collections/plus-security.mjs').then(m=>m.setupSecurityPlus),plusMoney:()=>import('./collections/plus-money.mjs').then(m=>m.setupMoneyPlus),plusBusiness:()=>import('./collections/plus-business.mjs').then(m=>m.setupBusinessPlus),plusLife:()=>import('./collections/plus-life.mjs').then(m=>m.setupLifePlus),plusNepal:()=>import('./collections/plus-nepal.mjs').then(m=>m.setupNepalPlus),speech:()=>import('./collections/speech.mjs').then(m=>m.setupSpeech),formatter:()=>import('./collections/formatter.mjs').then(m=>m.setupFormatter),anime:()=>import('./collections/anime.mjs').then(m=>m.setupAnime),worksheets:()=>import('./collections/worksheets.mjs').then(m=>m.setupWorksheets),qr:()=>import('./collections/qr.mjs').then(m=>m.setupQR),form:()=>import('./toolkit.mjs').then(m=>m.setupForm),timer:()=>import('./toolkit.mjs').then(m=>m.setupTimer),image:()=>import('./media.mjs').then(m=>m.setupImage),pdf:()=>import('./media.mjs').then(m=>m.setupPDF),creative:()=>import('./creative.mjs').then(m=>m.setupCreative),extra:()=>import('./extras.mjs').then(m=>m.setupExtra),advanced:()=>import('./advanced.mjs').then(m=>m.setupAdvanced),wellness:()=>import('./collections/wellness.mjs').then(m=>m.setupWellness),sport:()=>import('./collections/sport.mjs').then(m=>m.setupSport),learning:()=>import('./collections/learning.mjs').then(m=>m.setupLearning),life:()=>import('./collections/life.mjs').then(m=>m.setupLife),nepal:()=>import('./collections/nepal.mjs').then(m=>m.setupNepal),play:()=>import('./collections/play.mjs').then(m=>m.setupPlay),audio:()=>import('./collections/audio.mjs').then(m=>m.setupAudio),security:()=>import('./collections/security.mjs').then(m=>m.setupSecurity)};
async function activateTool(t,input,out,token){try{const fn=await toolLoaders[t.kind]();if(token!==activation)return;const dispose=fn(t,input,out);cleanup=typeof dispose==='function'?dispose:()=>{};}catch(err){if(token===activation)out.innerHTML=`<div class="error-box" role="alert">${e(err.message)}<p>Try reloading this page if the connection was interrupted.</p></div>`;}}
function recentTools(){const box=main.querySelector('[data-recent-section]');if(!box)return;const ids=read('nepocore-recent',[]);const list=(Array.isArray(ids)?ids:[]).map(id=>tools.find(t=>t.id===id)).filter(Boolean).slice(0,4);box.hidden=!list.length;box.querySelector('[data-recent-grid]').innerHTML=list.map(t=>cardHTML(t,favorites)).join('');}
function render({scroll=true}={}){clearOutput(main.querySelector('#tool-result'));clearOutput(main.querySelector('#tool-input'));activation++;if(scroll)sidebar.scrollTop=0;cleanup();cleanup=()=>{};closeMenu();legacyRoute();page=parsePage(location.pathname,baseURL.pathname);query=new URLSearchParams(location.search).get('q')||'';search.value=query;const preserveArticle=page.type==='article'&&main.querySelector('[data-blog-article]')?.dataset.blogArticle===page.id;if(!preserveArticle)main.innerHTML=pageHTML(page,{favorites,query,layout});nav();metadata();if(page.type==='article'&&!preserveArticle){const token=activation;loadArticle(page.id).then(article=>{if(token!==activation)return;main.innerHTML=pageHTML(page,{article});animate();if(location.hash)document.getElementById(location.hash.slice(1))?.scrollIntoView();}).catch(ex=>{if(token===activation)main.innerHTML='<div class="error-box" role="alert">'+e(ex.message)+'</div>';});}recentTools();if(page.type==='tool'){const t=tools.find(t=>t.id===page.id);const old=read('nepocore-recent',[]);save('nepocore-recent',[t.id,...(Array.isArray(old)?old:[]).filter(id=>id!==t.id)].slice(0,6));activateTool(t,main.querySelector('#tool-input'),main.querySelector('#tool-result'),activation);}animate();if(scroll){window.scrollTo({top:0,behavior:'auto'});main.focus({preventScroll:true});}}
function navigate(url,{replace=false}={}){history[replace?'replaceState':'pushState'](null,'',url);render();}
document.addEventListener('click',ev=>{const a=ev.target.closest('a[href]');if(!a||ev.defaultPrevented||ev.button!==0||ev.metaKey||ev.ctrlKey||ev.shiftKey||ev.altKey||a.hasAttribute('download')||a.target==='_blank')return;const raw=a.getAttribute('href');if(!raw||raw.startsWith('#')||/^(mailto:|tel:)/i.test(raw))return;const u=new URL(raw,document.baseURI);if(u.origin!==location.origin||!u.pathname.startsWith(baseURL.pathname))return;const p=parsePage(u.pathname,baseURL.pathname);if(p.type==='notfound')return;if(u.pathname===location.pathname&&u.hash){ev.preventDefault();history.pushState(null,'',u);document.getElementById(decodeURIComponent(u.hash.slice(1)))?.scrollIntoView({block:'start'});return;}ev.preventDefault();navigate(u);});
main.addEventListener('submit',ev=>{const blogForm=ev.target.closest('[data-blog-search]');if(blogForm){ev.preventDefault();const q=blogForm.querySelector('input').value.toLowerCase().trim(),list=blogIndex.filter(p=>(page.type!=='blogCategory'||p.category===page.id)&&(!q||q.split(/\s+/).every(word=>(p.title+' '+p.summary+' '+p.category).toLowerCase().includes(word))));main.querySelector('[data-guide-grid]').innerHTML=list.length?list.map(blogCard).join(''):'<p>No guides matched. Try a shorter phrase.</p>';main.querySelector('[data-guide-count]').textContent=list.length+' guides';return;}const f=ev.target.closest('[data-tool-search]');if(!f)return;ev.preventDefault();const dest=new URL(href('catalog'),baseURL),q=new FormData(f).get('q').trim();if(q)dest.searchParams.set('q',q);navigate(dest);});
main.addEventListener('click',ev=>{if(ev.target.closest('[data-clear-recent]')){save('nepocore-recent',[]);recentTools();return;}const star=ev.target.closest('[data-star]');if(star){ev.preventDefault();const id=star.dataset.star,t=tools.find(t=>t.id===id);if(favorites.has(id))favorites.delete(id);else favorites.add(id);save('nepocore-favorites',[...favorites]);main.querySelectorAll(`[data-star="${id}"]`).forEach(b=>b.outerHTML=starHTML(t,favorites));nav();if(page.type==='favorites')renderCards();notify(favorites.has(id)?'Added to your favorites':'Removed from favorites');return;}const view=ev.target.closest('[data-view]');if(view){layout=view.dataset.view;save('nepocore-layout',layout);renderCards();}if(ev.target.closest('[data-clear-search]')){search.value='';search.dispatchEvent(new Event('input'));}});
let searchTimer;search.addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{query=search.value.trim();const dest=new URL(href('catalog'),baseURL);if(query)dest.searchParams.set('q',query);history.replaceState(null,'',dest);if(!main.querySelector('#catalog-grid')||page.type!=='catalog'){clearOutput(main.querySelector('#tool-result'));clearOutput(main.querySelector('#tool-input'));activation++;cleanup();cleanup=()=>{};page={type:'catalog'};main.innerHTML=pageHTML(page,{query,favorites,layout});nav();animate();}else renderCards();const h=main.querySelector('h1');if(h&&page.type==='catalog')h.textContent=query?'Results for “'+query+'”':'All tools';const q=main.querySelector('#directory-query');if(q)q.value=query;metadata();},75);});
let ticking=false;function scrollProgress(){if(ticking)return;ticking=true;requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight,p=max>0?scrollY/max:0;document.documentElement.style.setProperty('--page-progress',String(p));document.querySelector('#back-top').hidden=scrollY<650;ticking=false;});}window.addEventListener('scroll',scrollProgress,{passive:true});document.querySelector('#back-top').onclick=()=>window.scrollTo({top:0,behavior:motion?'smooth':'auto'});
window.addEventListener('popstate',()=>render());window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#/'))render();});render({scroll:false});scrollProgress();
if('serviceWorker'in navigator&&location.protocol==='https:')window.addEventListener('load',()=>navigator.serviceWorker.register(new URL('./sw.js',baseURL)).catch(()=>{}));
